package com.smarthrms.service;
import com.smarthrms.dto.DepartmentDtos.*; import com.smarthrms.entity.Department; import com.smarthrms.exception.ApiException; import com.smarthrms.repository.DepartmentRepository; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @org.springframework.transaction.annotation.Transactional(readOnly=true) public class DepartmentService { private final DepartmentRepository repo; private Response out(Department d){return new Response(d.getId(),d.getName(),d.getLocation(),d.getManager(),d.getEmployees().size());} public List<Response> list(){return repo.findAll().stream().map(this::out).toList();} public Response get(Long id){return out(repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Department not found")));} @Transactional public Response create(Request r){if(repo.existsByNameIgnoreCase(r.name()))throw new ApiException(HttpStatus.CONFLICT,"Department already exists");return out(repo.save(Department.builder().name(r.name()).location(r.location()).manager(r.manager()).build()));} @Transactional public Response update(Long id,Request r){Department d=repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Department not found"));if(repo.existsByNameIgnoreCaseAndIdNot(r.name(),id))throw new ApiException(HttpStatus.CONFLICT,"Department already exists");d.setName(r.name());d.setLocation(r.location());d.setManager(r.manager());return out(repo.save(d));} @Transactional public void delete(Long id){Department d=repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Department not found"));if(!d.getEmployees().isEmpty())throw new ApiException(HttpStatus.CONFLICT,"Cannot delete a department with employees");repo.delete(d);} }
